CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Sales Totals by Amount` AS select `Order Subtotals`.`Subtotal` AS `SaleAmount`,`Orders`.`OrderID` AS `OrderID`,`Customers`.`CompanyName` AS `CompanyName`,`Orders`.`ShippedDate` AS `ShippedDate` from (`Customers` join (`Orders` join `Order Subtotals` on(`Orders`.`OrderID` = `Order Subtotals`.`OrderID`)) on(`Customers`.`CustomerID` = `Orders`.`CustomerID`)) where `Order Subtotals`.`Subtotal` > 2500 and `Orders`.`ShippedDate` between '1997-01-01' and '1997-12-31';
